use crate::{storage::Database,Runtime};use serde_json::{json,Value};use tauri::{AppHandle,Manager};
async fn operation<F>(app:AppHandle,confirmed:bool,action:F)->Result<Value,String>where F:FnOnce(&Database)->Result<Value,String>+Send+'static{if !confirmed{return Err("É necessária confirmação explícita".into())}tauri::async_runtime::spawn_blocking(move||{let runtime=app.state::<Runtime>();let _guard=runtime.operation.lock().map_err(|e|e.to_string())?;let db=app.state::<Database>();action(&db)}).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn power_plans()->Result<Value,String>{tauri::async_runtime::spawn_blocking(crate::power_manager::plans).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn apply_power_plan(app:AppHandle,id:String,expected:String,confirmed:bool)->Result<Value,String>{operation(app,confirmed,move|db|crate::power_manager::apply(db,&id,&expected)).await}
#[tauri::command]pub async fn preview_profile(mode:String)->Result<Value,String>{tauri::async_runtime::spawn_blocking(move||crate::profile_engine::preview(&mode)).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn apply_profile_action(app:AppHandle,id:String,previous:Value,confirmed:bool)->Result<Value,String>{operation(app,confirmed,move|db|crate::profile_engine::apply(db,&id,previous)).await}
#[tauri::command]pub async fn review_service(name:String)->Result<Value,String>{tauri::async_runtime::spawn_blocking(move||crate::service_changes::review(&name)).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn set_service_manual(app:AppHandle,name:String,expected:Value,confirmed:bool,feature_unused_confirmed:bool)->Result<Value,String>{operation(app,confirmed&&feature_unused_confirmed,move|db|crate::service_changes::apply(db,&name,&expected)).await}
#[tauri::command]pub async fn disable_task(app:AppHandle,path:String,fingerprint:String,confirmed:bool)->Result<Value,String>{operation(app,confirmed,move|db|crate::scheduled_tasks::disable(db,&path,&fingerprint)).await}
#[tauri::command]pub async fn restore_change(app:AppHandle,id:i64,confirmed:bool)->Result<Value,String>{operation(app,confirmed,move|db|crate::rollback_manager::restore(db,id)).await}
#[tauri::command]pub async fn preview_game_session(mode:String)->Result<Value,String>{tauri::async_runtime::spawn_blocking(move||crate::game_sessions::preview(&mode)).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn launch_game_session(app:AppHandle,id:i64,mode:String,expected:String,confirmed:bool)->Result<Value,String>{if !confirmed{return Err("Confirme o lançamento e as alterações temporárias".into())}tauri::async_runtime::spawn_blocking(move||crate::game_sessions::launch(app,id,&mode,&expected)).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn recycle_info()->Result<Value,String>{tauri::async_runtime::spawn_blocking(crate::storage_tools::recycle_info).await.map_err(|e|e.to_string())?}
#[tauri::command]pub async fn empty_recycle(app:AppHandle,confirmed:bool)->Result<Value,String>{operation(app,confirmed,move|db|{db.log("recycle.intent","Utilizador confirmou eliminação permanente; confirmação nativa ativa")?;let result=crate::storage_tools::empty_recycle()?;db.log("recycle.result",&result.to_string())?;Ok(result)}).await}
#[tauri::command]pub async fn large_files(root:String,threshold_mb:u64)->Result<Value,String>{tauri::async_runtime::spawn_blocking(move||crate::storage_tools::large_files(&root,threshold_mb)).await.map_err(|e|e.to_string())?}
#[tauri::command]pub fn open_documentation(page:String)->Result<Value,String>{let url=match page.as_str(){"fortnite"=>"https://www.epicgames.com/help/c-34254770/c-37371353/a22311370","gtav"=>"https://support.rockstargames.com/","valorant"=>"https://support-valorant.riotgames.com/","cs2"=>"https://help.steampowered.com/en/wizard/HelpWithGame/?appid=730",_=>return Err("Documento fora da allowlist".into())};let url:Vec<u16>=url.encode_utf16().chain(Some(0)).collect();let result=unsafe{windows_sys::Win32::UI::Shell::ShellExecuteW(std::ptr::null_mut(),std::ptr::null(),url.as_ptr(),std::ptr::null(),std::ptr::null(),1)};if result as isize<=32{return Err("Não foi possível abrir o navegador".into())}Ok(json!({"opened":true}))}
